// tl.ts: the hand-set timeline (no VO), generated by 4-animation/build/timeline.py from the reading-time rule.
// The picture and build/sfx.py both read src/data/timeline.json, so sound and picture stay in sync.
import tl from '../data/timeline.json';

type Card = {on: number; landed: number; off: number; words: number; min: number};
export const TL = tl as unknown as {
  total: number;
  endScreen: {start: number; dur: number};
  scenes: Record<string, {start: number; end: number}>;
  cards: Record<string, Card>;
  ev: Record<string, any>;
};
export const S = (k: string) => TL.scenes[k].start;
export const E = (k: string) => TL.scenes[k].end;
export const CARD = (k: string) => TL.cards[k];
export const EV = TL.ev;
